import math
from sympy.abc import x, y, z
from sympy import Rational, Integer

# Top-level setup
# The witness is expected to be a tuple (n, S_list) representing:
# - R = Z (the ring of integers)
# - I = nZ (the ideal generated by n)
# - S = S_list (a subset of Z, not necessarily multiplicatively closed)

def conditions(witness):
    """
    Checks if the given witness is a valid counterexample to the false conjecture.
    The witness should be of the form (n, S_list) where n is an integer and S_list is a list of integers.
    """
    try:
        if len(witness) != 2:
            return [False, False, False, False]
        n, S_list = witness
        n = int(n)
        S_list = list(S_list)
        S_list = [int(s) for s in S_list]
    except Exception:
        return [False, False, False, False]
    
    # H_1: R is a commutative ring
    # The domain Z is always a commutative ring.
    h1 = True
    
    # H_2: I is an ideal of R
    # nZ is always an ideal in Z.
    h2 = True
    
    # H_3: \phi is the canonical localization map from R to S^{-1}R
    # This is true by the definition of the setup.
    h3 = True
    
    try:
        # Calculate the generator 'm' of the contraction of the extended ideal \phi^{-1}(S^{-1}I).
        # In Z, this corresponds to removing all prime factors from n that appear in any element of S.
        if n == 0:
            if not S_list:
                neg_q = True
            else:
                neg_q = False
        else:
            n_abs = abs(n)
            if 0 in S_list:
                m = 1
            else:
                m = n_abs
                for s in S_list:
                    if s == 0:
                        m = 1
                        break
                    s_abs = abs(s)
                    if s_abs == 1:
                        continue
                    g = math.gcd(m, s_abs)
                    while g > 1:
                        m //= g
                        g = math.gcd(m, s_abs)
            
            # The right-hand side of the conclusion is C = {x \in Z | \exists s \in S such that sx \in nZ}.
            # Since C is a union of ideals and \phi^{-1}(S^{-1}I) = mZ, they are equal if and only if m \in C.
            # m \in C iff there exists s \in S such that s * m is a multiple of n.
            conclusion_holds = any((s * m) % n == 0 for s in S_list)
            
            # The conclusion FAILS if they are not equal.
            neg_q = not conclusion_holds
            
    except Exception:
        neg_q = False
        
    return [h1, h2, h3, neg_q]

CONDITION_LABELS = [
    "H_1: R is a commutative ring",
    "H_2: I is an ideal of R",
    "H_3: \\phi is the canonical localization map from R to S^{-1}R",
    "¬Q: The contraction \\phi^{-1}(S^{-1}I) is NOT equal to {x \\in R | \\exists s \\in S such that sx \\in I}"
]

